def md(d, nd=2):
    d = d.copy()
    for c in d.columns:
        if d[c].dtype.kind == "f": d[c] = d[c].map(lambda x: "" if pd.isna(x) else (f"{x:.0f}" if float(x).is_integer() and abs(x) >= 1 else f"{x:.{nd}f}"))
    return "\n".join(["| " + " | ".join(map(str, d.columns)) + " |", "|" + "---|" * len(d.columns)] + ["| " + " | ".join(map(str, r)) + " |" for r in d.astype(str).values]) + "\n"


